we have $W = \prod_{I \in \II(\overline \mu, 0)} S(I)$ and $W_z = \prod_{I \in \II(\overline \mu, z)} S(I)$ for each $z \in \Z(\vv)$, which are Young subgroups of $S_\mu$.

The following lemma describes the action of $U$ on $V(\Omega, T(\vv))$ in terms of the basis given in Theorem <<ref:T:direct-sum>>. In order to state the lemma we need to fix some notation which we will also use in the irreducibility criterion Theorem <<ref:T:simplicity>>. Given $z \in \Z(\vv)$ and $1 \leq k \leq r'$ we will denote by $\II_k(\overline \mu, z)$ the subset of $\II(\overline \mu, z)$ consisting of sets of the form $I = \{(k,i), 
\ldots, (k,j)\}$. We also write $\sigma^+(I) = (j \ j-1 \ \cdots \ i)^{(k)}$ and $\sigma^-(I) = (i \ i+1 \ \cdots \ j)^{(k)}$. \begin{Lemma}

Let $\vv \in \CC^{\mu}$ be a seed and let $z \in \Z(\vv)$. For each $1 \leq k 
\leq r'$ we have

\begin{align*}
(X^\pm_k)^\dagger
&= \sum_{I \in \II_k(\overline \mu, z)}
\frac{1}{|\widetilde W_{a^\mp(I)}|} \partial_{\sigma^\mp(I)}
\left(
\frac{f^\pm_{a^{\mp}(I)}}{\prod_{(k,j) \notin I} (x_{a^\mp(I)}-x_{k,j})}
t_{a^{\mp}(I)}^{\mp 1}
\right);,\\
\DD{}{\sigma}{\vv+z} \circ (X_k^\pm)^\dagger
&= \sum_{I \in \II_k(\overline \mu, z, \sigma^\mp(I))}
\sum_{\tau \leq \sigma \sigma^\mp(I)}
\D{}{\tau, \sigma \sigma^\mp(I)}{\vv + z} \left(
\frac{f^\pm_{a^\mp(I)}}{\displaystyle
\prod_{(k,j) \notin I} (x_{a^\mp(I)} - x_{k,j})}
\right) \DD{}{\tau}{\vv + z + \delta(\mp I)},
\end{align*}

where $\II_k(\overline \mu, z, \sigma^\mp(I))$ is the subset of $\II_k(\overline \mu, z)$ consisting of all $I$ such that $\ell(\sigma 
\sigma^\mp(I)) = \ell(\sigma) + \ell(\sigma^\mp(I))$ and $\delta(\mp I) = 
\delta^{a^\mp(I)}$. \end{Lemma}
